style.css:
@-moz-document domain("youtube.com") {
/* =====================================================
       SKYDUSK YOUTUBE THEME
       ===================================================== */


    /* =====================================================
       1. YOUTUBE BACKGROUND VARIABLES
       ===================================================== */

    html[dark],
    html[darker-dark-theme-deprecate] {

        --yt-sys-color-baseline--base-background:
            transparent !important;

        --yt-deprecated-general-background-a:
            transparent !important;

        --yt-deprecated-general-background-b:
            transparent !important;

        --yt-deprecated-general-background-c:
            transparent !important;

        --yt-spec-general-background-a:
            transparent !important;

        --yt-spec-general-background-b:
            transparent !important;

        --yt-spec-general-background-c:
            transparent !important;

        --yt-spec-base-background:
            transparent !important;

        --yt-spec-raised-background:
            transparent !important;
    }


    /* =====================================================
       2. COLORS
       ===================================================== */

    :root {

        --sky-dark:
            #161a1c;

        --sky-bg:
            #262c2f;

        --sky-text:
            #bdc4cc;

        --sky-black:
            #000000;
    }


    /* =====================================================
       3. MAIN WALLPAPER
       ===================================================== */

    html {

        background-color:
            #262c2f !important;
    }

    body {

        background-color:
            #262c2f !important;

        background-image:
            url("https://i.pinimg.com/736x/77/43/49/774349e2c35ecc9626704a5d232e867e.jpg") !important;

        background-repeat:
            repeat !important;

        background-size:
            450px 450px !important;

        background-position:
            center center !important;

        background-attachment:
            fixed !important;
    }


    /* =====================================================
       4. MAIN YOUTUBE LAYERS
       ===================================================== */

    ytd-app,
    ytd-page-manager,
    #page-manager,
    #content,
    ytd-browse,
    ytd-search,
    ytd-two-column-browse-results-renderer,
    ytd-rich-grid-renderer,
    ytd-rich-grid-row,
    ytd-item-section-renderer,
    ytd-section-list-renderer {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       5. HOME GRID BACKGROUND
       ===================================================== */

    #contents,
    ytd-rich-grid-renderer #contents,
    ytd-rich-grid-row #contents {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       6. MAIN COLUMNS
       ===================================================== */

    #columns,
    #primary,
    #secondary,
    #primary-inner,
    #secondary-inner {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       7. TOP BAR
       ===================================================== */

    #masthead-container,
    ytd-masthead {

        background-color:
            #161a1c !important;

        background-image:
            none !important;

        border-bottom:
            2px solid #000 !important;

        box-shadow:
            0 0 15px 2px #000 !important;
    }


    /* =====================================================
       8. SIDEBAR
       ===================================================== */

    ytd-guide-renderer {

        background-color:
            #161a1c !important;

        background-image:
            none !important;

        border-right:
            2px solid #000 !important;

        box-shadow:
            4px 0 10px rgba(0,0,0,.8) !important;
    }

    ytd-guide-content-renderer,
    #guide-inner-content {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       9. SIDEBAR ITEMS
       ===================================================== */

    ytd-guide-entry-renderer,
    ytd-mini-guide-entry-renderer {

        color:
            #bdc4cc !important;

        border-radius:
            8px !important;
    }

    ytd-guide-entry-renderer:hover,
    ytd-mini-guide-entry-renderer:hover {

        background-color:
            #262c2f !important;
    }


    /* =====================================================
       10. CATEGORY BAR
       ===================================================== */

    ytd-feed-filter-chip-bar-renderer {

        background-color:
            rgba(22,26,28,.94) !important;

        background-image:
            none !important;

        border-bottom:
            2px solid #000 !important;
    }


    /* =====================================================
       11. CATEGORY BUTTONS
       ===================================================== */

    yt-chip-cloud-chip-renderer {

        background-color:
            #262c2f !important;

        color:
            #bdc4cc !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        box-shadow:
            3px 3px 5px #000 !important;
    }

    yt-chip-cloud-chip-renderer:hover {

        background-color:
            #161a1c !important;
    }


    /* =====================================================
       12. VIDEO CARDS
       ===================================================== */

    ytd-rich-item-renderer {

        background-color:
            rgba(22,26,28,.88) !important;

        background-image:
            none !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        padding:
            8px !important;

        box-shadow:
            5px 5px 8px rgba(0,0,0,.85) !important;

        box-sizing:
            border-box !important;
    }


    /* =====================================================
       13. CARD INTERNAL CONTENT
       ===================================================== */

    ytd-rich-item-renderer #content,
    ytd-rich-item-renderer #dismissible,
    ytd-rich-item-renderer #details {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       14. THUMBNAILS
       ===================================================== */

    ytd-thumbnail {

        background-color:
            #161a1c !important;

        border-radius:
            7px !important;

        overflow:
            hidden !important;
    }

    ytd-thumbnail img {

        filter:
            saturate(.80)
            contrast(1.08) !important;
    }


    /* =====================================================
       15. VIDEO TITLES
       ===================================================== */

    #video-title {

        color:
            #bdc4cc !important;

        text-shadow:
            0 0 7px #000 !important;
    }

    #channel-name,
    #metadata-line {

        color:
            #bdc4cc !important;
    }


    /* =====================================================
       16. SEARCH RESULTS
       ===================================================== */

    ytd-video-renderer,
    ytd-playlist-renderer,
    ytd-channel-renderer,
    ytd-grid-video-renderer {

        background-color:
            rgba(22,26,28,.88) !important;

        background-image:
            none !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        padding:
            8px !important;

        margin-bottom:
            10px !important;

        box-shadow:
            5px 5px 8px rgba(0,0,0,.85) !important;
    }


    /* =====================================================
       17. VIDEO PAGE
       ===================================================== */

    ytd-watch-flexy {

        background-color:
            transparent !important;

        background-image:
            none !important;
    }


    /* =====================================================
       18. PLAYER
       ===================================================== */

    #player-container,
    #player,
    #player-theater-container {

        border-radius:
            10px !important;

        overflow:
            hidden !important;

        box-shadow:
            0 0 18px 4px #000 !important;
    }


    /* =====================================================
       19. VIDEO INFORMATION
       ===================================================== */

    ytd-watch-metadata,
    ytd-video-primary-info-renderer,
    ytd-video-secondary-info-renderer {

        background-color:
            rgba(22,26,28,.90) !important;

        background-image:
            none !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        box-shadow:
            5px 5px 8px rgba(0,0,0,.85) !important;
    }


    /* =====================================================
       20. COMMENTS
       ===================================================== */

    ytd-comments {

        background-color:
            rgba(22,26,28,.90) !important;

        background-image:
            none !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        box-shadow:
            5px 5px 8px rgba(0,0,0,.85) !important;
    }


    /* =====================================================
       21. SEARCH BOX
       ===================================================== */

    ytd-searchbox,
    ytd-searchbox #container {

        background-color:
            #262c2f !important;

        background-image:
            none !important;
    }

    ytd-searchbox #container {

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        box-shadow:
            4px 4px 8px #000 !important;
    }


    /* =====================================================
       22. POPUP MENUS
       ===================================================== */

    ytd-popup-container,
    ytd-menu-popup-renderer,
    ytd-multi-page-menu-renderer {

        background-color:
            #262c2f !important;

        background-image:
            none !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;

        box-shadow:
            0 0 20px #000 !important;
    }


    /* =====================================================
       23. TEXT
       ===================================================== */

    yt-formatted-string,
    yt-attributed-string {

        color:
            #bdc4cc !important;
    }

    a {

        color:
            #bdc4cc !important;
    }

    a:hover {

        color:
            #ffffff !important;
    }


    /* =====================================================
       24. AVATARS
       ===================================================== */

    yt-img-shadow,
    yt-img-shadow img,
    #avatar {

        border-radius:
            50% !important;
    }


    /* =====================================================
       25. SCROLLBAR
       ===================================================== */

    ::-webkit-scrollbar {

        width:
            12px !important;
    }

    ::-webkit-scrollbar-track {

        background:
            #161a1c !important;
    }

    ::-webkit-scrollbar-thumb {

        background:
            #262c2f !important;

        border:
            2px solid #000 !important;

        border-radius:
            10px !important;
    }

    ::-webkit-scrollbar-thumb:hover {

        background:
            #bdc4cc !important;
    }


    /* =====================================================
       26. CURSORS
       ===================================================== */

    * {

        cursor:
            url("https://files.catbox.moe/qechfa.gif"),
            auto !important;
    }

    a,
    button,
    yt-icon-button,
    yt-chip-cloud-chip-renderer {

        cursor:
            url("https://files.catbox.moe/tqq4nf.gif"),
            pointer !important;
    }
}
